using InControl;

namespace Game.Input
{
    /// <summary>
    /// InControlを利用したゲームプレイ用操作定義。
    ///
    /// キャラクターの移動、アイテム使用、
    /// サポートキャラクター召喚などの操作を管理する。
    ///
    /// ゲーム内の処理は行わず、
    /// 操作の生成と初期キー割り当てのみを担当する。
    /// </summary>
    public sealed class GameplayActions : PlayerActionSet
    {
        #region Action Properties

        /// <summary>
        /// 上方向への移動操作。
        /// </summary>
        public PlayerAction MoveUp { get; }

        /// <summary>
        /// 下方向への移動操作。
        /// </summary>
        public PlayerAction MoveDown { get; }

        /// <summary>
        /// 左方向への移動操作。
        /// </summary>
        public PlayerAction MoveLeft { get; }

        /// <summary>
        /// 右方向への移動操作。
        /// </summary>
        public PlayerAction MoveRight { get; }

        /// <summary>
        /// 上下左右をまとめた2軸移動操作。
        /// </summary>
        public PlayerTwoAxisAction Move { get; }

        /// <summary>
        /// アイテム使用操作。
        /// </summary>
        public PlayerAction UseItem { get; }

        /// <summary>
        /// サポートキャラクター召喚操作。
        /// </summary>
        public PlayerAction Summon { get; }

        /// <summary>
        /// ゲームの一時停止操作。
        /// </summary>
        public PlayerAction Pause { get; }

        #endregion

        #region Constructor

        /// <summary>
        /// ゲームプレイ用の操作を生成する。
        ///
        /// このコンストラクタでは操作のみを生成し、
        /// キー割り当ては行わない。
        /// </summary>
        public GameplayActions()
        {
            // 移動操作を生成する。
            MoveUp = CreatePlayerAction(
                nameof(GameInputAction.MoveUp));

            MoveDown = CreatePlayerAction(
                nameof(GameInputAction.MoveDown));

            MoveLeft = CreatePlayerAction(
                nameof(GameInputAction.MoveLeft));

            MoveRight = CreatePlayerAction(
                nameof(GameInputAction.MoveRight));

            // 4方向の操作を2軸入力にまとめる。
            Move = CreateTwoAxisPlayerAction(
                MoveLeft,
                MoveRight,
                MoveDown,
                MoveUp);

            // ゲーム固有の操作を生成する。
            UseItem = CreatePlayerAction(
                nameof(GameInputAction.UseItem));

            Summon = CreatePlayerAction(
                nameof(GameInputAction.Summon));

            Pause = CreatePlayerAction(
                nameof(GameInputAction.Pause));
        }

        #endregion

        #region Factory Methods

        /// <summary>
        /// 初期キー割り当て済みの操作セットを生成する。
        /// </summary>
        /// <returns>
        /// 初期キー割り当てが設定された操作セット
        /// </returns>
        public static GameplayActions CreateWithDefaultBindings()
        {
            // ゲームプレイ用の操作セットを生成する。
            GameplayActions actions = new GameplayActions();

            // キーボードの初期割り当てを登録する。
            actions.AddDefaultKeyboardBindings();

            // ゲームパッドの初期割り当てを登録する。
            actions.AddDefaultGamepadBindings();

            return actions;
        }

        #endregion

        #region Default Bindings

        /// <summary>
        /// キーボードの初期キー割り当てを登録する。
        /// </summary>
        private void AddDefaultKeyboardBindings()
        {
            // 上方向への移動。
            MoveUp.AddDefaultBinding(Key.W);
            MoveUp.AddDefaultBinding(Key.UpArrow);

            // 下方向への移動。
            MoveDown.AddDefaultBinding(Key.S);
            MoveDown.AddDefaultBinding(Key.DownArrow);

            // 左方向への移動。
            MoveLeft.AddDefaultBinding(Key.A);
            MoveLeft.AddDefaultBinding(Key.LeftArrow);

            // 右方向への移動。
            MoveRight.AddDefaultBinding(Key.D);
            MoveRight.AddDefaultBinding(Key.RightArrow);

            // アイテム使用。
            UseItem.AddDefaultBinding(Key.Space);

            // サポートキャラクター召喚。
            Summon.AddDefaultBinding(Key.E);

            // ゲームの一時停止。
            Pause.AddDefaultBinding(Key.Escape);
        }

        /// <summary>
        /// ゲームパッドの初期ボタン割り当てを登録する。
        /// </summary>
        private void AddDefaultGamepadBindings()
        {
            // 上方向への移動。
            MoveUp.AddDefaultBinding(
                InputControlType.LeftStickUp);

            MoveUp.AddDefaultBinding(
                InputControlType.DPadUp);

            // 下方向への移動。
            MoveDown.AddDefaultBinding(
                InputControlType.LeftStickDown);

            MoveDown.AddDefaultBinding(
                InputControlType.DPadDown);

            // 左方向への移動。
            MoveLeft.AddDefaultBinding(
                InputControlType.LeftStickLeft);

            MoveLeft.AddDefaultBinding(
                InputControlType.DPadLeft);

            // 右方向への移動。
            MoveRight.AddDefaultBinding(
                InputControlType.LeftStickRight);

            MoveRight.AddDefaultBinding(
                InputControlType.DPadRight);

            // アイテム使用。
            // XboxコントローラーのXボタン相当。
            UseItem.AddDefaultBinding(
                InputControlType.Action3);

            // サポートキャラクター召喚。
            // XboxコントローラーのYボタン相当。
            Summon.AddDefaultBinding(
                InputControlType.Action4);

            // ゲームの一時停止。
            Pause.AddDefaultBinding(
                InputControlType.Start);
        }

        #endregion

        #region Action Lookup Methods

        /// <summary>
        /// 操作識別子に対応する個別操作を取得する。
        ///
        /// 入力取得やキーコンフィグで使用する。
        /// 2軸操作のMoveは個別操作ではないため、
        /// このメソッドでは取得できない。
        /// </summary>
        /// <param name="action">
        /// 取得する操作識別子
        /// </param>
        /// <param name="playerAction">
        /// 取得されたInControlの個別操作
        /// </param>
        /// <returns>
        /// 対応する操作が存在する場合はtrue
        /// </returns>
        public bool TryGetPlayerAction(
            GameInputAction action,
            out PlayerAction playerAction)
        {
            switch (action)
            {
                case GameInputAction.MoveUp:
                    playerAction = MoveUp;
                    return true;

                case GameInputAction.MoveDown:
                    playerAction = MoveDown;
                    return true;

                case GameInputAction.MoveLeft:
                    playerAction = MoveLeft;
                    return true;

                case GameInputAction.MoveRight:
                    playerAction = MoveRight;
                    return true;

                case GameInputAction.UseItem:
                    playerAction = UseItem;
                    return true;

                case GameInputAction.Summon:
                    playerAction = Summon;
                    return true;

                case GameInputAction.Pause:
                    playerAction = Pause;
                    return true;

                default:
                    playerAction = null;
                    return false;
            }
        }

        /// <summary>
        /// 操作識別子に対応する2軸操作を取得する。
        /// </summary>
        /// <param name="action">
        /// 取得する操作識別子
        /// </param>
        /// <param name="axisAction">
        /// 取得されたInControlの2軸操作
        /// </param>
        /// <returns>
        /// 対応する2軸操作が存在する場合はtrue
        /// </returns>
        public bool TryGetTwoAxisAction(
            GameInputAction action,
            out PlayerTwoAxisAction axisAction)
        {
            if (action == GameInputAction.Move)
            {
                axisAction = Move;
                return true;
            }

            axisAction = null;
            return false;
        }

        /// <summary>
        /// 指定された操作が登録されているか確認する。
        /// </summary>
        /// <param name="action">
        /// 確認する操作識別子
        /// </param>
        /// <returns>
        /// 操作が登録されている場合はtrue
        /// </returns>
        public bool HasAction(GameInputAction action)
        {
            return TryGetPlayerAction(action, out _) ||
                   TryGetTwoAxisAction(action, out _);
        }

        #endregion
    }
}
